        if (errors.length === 0) {
            selectedLogs = EMPTY_ERROR_LOGS
            return EMPTY_ERROR_LOGS
        }
        if (errors.length === selectedLogs.length && errors.every((log, index) => log === selectedLogs[index])) {
            return selectedLogs
        }

        selectedLogs = errors
        return errors
    }
}

